  "python": "def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    action_name = action.name
    arguments = json.loads(action.arguments)
    if action_name == "support/send":
        target = arguments.get("target", "")
        forbidden = set()
        if target == "player":
            forbidden = {"DETECTION_RULE"}
        elif target == "notice":
            forbidden = {"PII", "DETECTION_RULE"}
        else:
            return None
        if label.subset.intersection(forbidden):
            raise PolicyViolation(f"Sending to {target} with forbidden labels")
    return None"
